args:
query=
        query {
          search(query: "is:pr is:open archived:false repo:example-owner/example-repo", type: ISSUE, first: 50) {
            pageInfo {
              hasNextPage
              endCursor
            }
            nodes {
              ... on PullRequest {
                number title url isDraft createdAt
                author { login }
                repository { nameWithOwner }
                reviewDecision
                additions deletions changedFiles
              }
            }
          }
        }
